      decimal digit.

    The pattern is therefore translated (``$`` -> ``\\Z`` outside character
    classes, ``\\d``/``\\D`` -> ASCII digit classes) and applied with
    ``search``, which preserves the unanchored search semantics JSON Schema
    assigns to ``pattern``.
    """
    translated: list = []
    in_class = False
    index = 0
    while index < len(pattern):
        char = pattern[index]
        if char == "\\" and index + 1 < len(pattern):
            following = pattern[index + 1]
            if following == "d":
                translated.append("0-9" if in_class else "[0-9]")
            elif following == "D":
